import * as T from 'three';
import {audio} from '../presentation/audio.js';
const V=(x=0,y=0,z=0)=>new T.Vector3(x,y,z),UP=V(0,1,0);
export const PALETTES={poison:[0x6fbd86,0xc3ec9c,0x264e43],fire:[0xff5a13,0xffc065,0x8b260a],ice:[0x75cfff,0xe1faff,0x287fd0],lightning:[0x8b9bff,0xf3edff,0x514de0],wind:[0xb3c8c5,0xf4e3b4,0x748a86],arrow:[0xc6ae77,0xf2df9d,0x7d6c4d],holy:[0xf6ca68,0xfff0b9,0x96814a],physical:[0xcdc1a0,0xffeac1,0x796957]};
export function effectFor(spec,family){if(spec.skillId==='barbarian-0-3')return'wind';if(spec.skillId?.startsWith('sorceress-0'))return'fire';if(spec.skillId?.startsWith('sorceress-1'))return'ice';if(spec.skillId?.startsWith('sorceress-2'))return'lightning';if(spec.skillId?.startsWith('paladin'))return'holy';if(['bow','crossbow','throwaxe','throwknife'].includes(family))return'arrow';if(['staff','wand'].includes(family))return'fire';return'physical';}
function glowTexture(){const c=document.createElement('canvas');c.width=c.height=64;const x=c.getContext('2d'),g=x.createRadialGradient(32,32,0,32,32,32);g.addColorStop(0,'rgba(255,255,255,1)');g.addColorStop(.13,'rgba(255,255,255,.95)');g.addColorStop(.4,'rgba(255,255,255,.28)');g.addColorStop(1,'rgba(255,255,255,0)');x.fillStyle=g;x.fillRect(0,0,64,64);return new T.CanvasTexture(c);}
const basic=(color,opacity=1)=>new T.MeshBasicMaterial({color,transparent:true,opacity,depthWrite:false,blending:T.AdditiveBlending,side:T.DoubleSide,toneMapped:false});
export class CombatEffects{
 constructor(scene){this.scene=scene;this.texture=glowTexture();this.entities=[];this.particles=[];this.history=[];this.time=0;this.sound=false;this.fx=1;this.maxParticles=innerWidth<600?550:1100;const g=new T.BufferGeometry();this.positions=new Float32Array(this.maxParticles*3);this.colors=new Float32Array(this.maxParticles*3);g.setAttribute('position',new T.BufferAttribute(this.positions,3));g.setAttribute('color',new T.BufferAttribute(this.colors,3));this.points=new T.Points(g,new T.PointsMaterial({size:.13,map:this.texture,transparent:true,depthWrite:false,vertexColors:true,blending:T.AdditiveBlending,toneMapped:false,sizeAttenuation:true}));this.points.frustumCulled=false;scene.add(this.points);this.lightPool=Array.from({length:4},()=>{const light=new T.PointLight(0xffffff,0,5,2);scene.add(light);return{light,life:0,duration:1,power:0};});}
 // 전투 화면은 카메라가 멀어 이펙트를 키운다(장비 시험실은 1 그대로). 판정과는 무관한 그림 배율이다.
 setFx(f){this.fx=f;this.points.material.size=.13*(1+(f-1)*.9);for(const e of this.lightPool)e.light.distance=5*f;}
 ghost(kind,pos,size=.6,life=.28){const s=this.sprite(kind,size);s.position.copy(pos);this.add(s,life,(e,t)=>{s.scale.setScalar(size*(1-.55*t));s.material.opacity=(1-t)*.75;});}
 scorch(kind,pos,radius){const look={fire:[0x120805,.36,T.NormalBlending],ice:[0xbfefff,.34,T.AdditiveBlending],lightning:[0x8b9bff,.26,T.AdditiveBlending]}[kind];if(!look||this.entities.filter(e=>e.decal).length>=16)return;const mesh=new T.Mesh(new T.CircleGeometry(Math.max(.45,radius),28),new T.MeshBasicMaterial({color:look[0],transparent:true,opacity:look[1],depthWrite:false,blending:look[2],toneMapped:false}));mesh.rotation.x=-Math.PI/2;mesh.position.set(pos.x,.03,pos.z);this.add(mesh,2.6,(e,t)=>{mesh.material.opacity=look[1]*(1-t)**1.5;}).decal=true;}
 burst(kind,pos){const p=pos.clone().setY(.9);this.dust(kind,p,22,3.4,.55);this.ring(kind,pos,1.0,.4);const s=this.sprite(kind,1);s.position.copy(p);this.add(s,.22,(e,t)=>{s.scale.setScalar((.6+t*2.6)*this.fx);s.material.opacity=1-t;});}
 wedge(pos,yaw,reach=1.7,life=.45){const g=new T.Group(),angle=1.5,mesh=new T.Mesh(new T.CircleGeometry(reach,18,-Math.PI/2-angle/2,angle),basic(0xff3b1e,.3));mesh.rotation.x=-Math.PI/2;g.add(mesh);g.position.set(pos.x,.04,pos.z);g.rotation.y=yaw;this.add(g,life,(e,t)=>{mesh.material.opacity=.12+.3*t;mesh.scale.setScalar(.55+.45*t);});}
 event(type,kind,pos){audio.effect(type,kind,this.weaponFamily);this.history.push({type,kind,time:this.time,position:pos?.toArray()});this.history=this.history.slice(-120);}
 sprite(kind,size=1){const s=new T.Sprite(new T.SpriteMaterial({map:this.texture,color:PALETTES[kind][0],transparent:true,depthWrite:false,blending:T.AdditiveBlending,toneMapped:false}));s.scale.setScalar(size);return s;}
 add(root,life,update=()=>{}){this.scene.add(root);const e={root,life,age:0,update,dead:false};this.entities.push(e);return e;}
 remove(e){if(!e||e.dead)return;e.dead=true;e.root.removeFromParent();e.root.traverse(o=>{o.geometry?.dispose();if(o.material){if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material.dispose();}});}
 dust(kind,pos,count=14,speed=2,life=.6){const palette=PALETTES[kind];if(this.fx>1){count=Math.round(count*1.35);speed*=1+(this.fx-1)*.5;}for(let i=0;i<count&&this.particles.length<this.maxParticles;i++){const velocity=V(Math.random()-.5,Math.random()*.8,Math.random()-.5).normalize().multiplyScalar(speed*(.3+Math.random()));this.particles.push({p:pos.clone(),v:velocity,age:0,life:life*(.5+Math.random()),color:new T.Color(palette[i%3]),gravity:kind==='ice'?-2:kind==='fire'?.7:-.4});}}
 light(kind,pos,life=.2,power=5){const entry=this.lightPool.find(e=>e.life<=0)||this.lightPool.reduce((a,b)=>a.life<b.life?a:b);if(this.fx>1)power*=1.8;Object.assign(entry,{life,duration:life,power});entry.light.color.setHex(PALETTES[kind][0]);entry.light.position.copy(pos);entry.light.intensity=power;}
 charge(kind,bone,life=.3){if(!PALETTES[kind]||kind==='physical'||kind==='arrow')return;const root=new T.Group(),s=this.sprite(kind,.6);root.add(s);this.event('charge',kind,bone.getWorldPosition(V()));this.add(root,life,(e,t)=>{root.position.copy(bone.getWorldPosition(V()));s.scale.setScalar(.15+.65*t);s.material.opacity=.4+.5*t;if(Math.random()<.4)this.dust(kind,root.position,1,.3,.25);});}
 missile(kind,start,direction,{family='staff',orb=false,silent=false,hammer=false,charged=false,arrow=false}={}){const root=new T.Group(),palette=PALETTES[kind];if(hammer){const shaft=new T.Mesh(new T.CylinderGeometry(.025,.025,.43,8),basic(0xffd077));shaft.rotation.x=Math.PI/2;root.add(shaft);const head=new T.Mesh(new T.BoxGeometry(.43,.16,.18),basic(0xffebad));head.position.z=.22;root.add(head);root.add(this.sprite('holy',.8));}else if(charged){const pts=[];for(let i=0;i<9;i++)pts.push(V(Math.sin(i*2.5)*.10,0,(i/8-.5)*.7));const bolt=new T.Mesh(new T.TubeGeometry(polyline(pts),20,.018,4),basic(0xd6d8ff));root.add(bolt);root.add(this.sprite('lightning',.5));}else if(kind==='arrow'||arrow){
  const shaft=new T.Mesh(new T.CylinderGeometry(.009,.009,.58,8),new T.MeshStandardMaterial({color:0x88724a,roughness:.8}));shaft.rotation.x=Math.PI/2;root.add(shaft);const head=new T.Mesh(new T.ConeGeometry(.035,.13,4),new T.MeshStandardMaterial({color:0xbfcac9,metalness:.8,roughness:.3}));head.rotation.x=Math.PI/2;head.position.z=.35;root.add(head);for(const sign of [-1,1]){const f=new T.Mesh(new T.PlaneGeometry(.075,.13),new T.MeshBasicMaterial({color:0xc4bda5,side:T.DoubleSide}));f.position.set(sign*.025,0,-.22);f.rotation.y=sign*.35;root.add(f);}if(kind!=='arrow')root.add(this.sprite(kind,.45));
 }else if(kind==='ice'){const shard=new T.Mesh(new T.OctahedronGeometry(orb?.23:.13,0),new T.MeshStandardMaterial({color:0xc9f3ff,emissive:0x3483c0,emissiveIntensity:1.4,metalness:.5,roughness:.15}));if(!orb)shard.scale.set(.55,.55,2.4);root.add(shard);const halo=this.sprite(kind,orb?1.2:.65);root.add(halo);if(orb){for(let i=0;i<2;i++){const ring=new T.Mesh(new T.TorusGeometry(.31,.014,6,40),basic(0xb9edff,.8));ring.rotation.set(i*.8,.5+i*.7,0);root.add(ring);}}}
 else{const core=new T.Mesh(new T.IcosahedronGeometry(orb?.23:.13,1),basic(palette[1]));root.add(core);root.add(this.sprite(kind,orb?1.3:.8));const flame=this.sprite(kind,.6);flame.position.z=-.18;flame.scale.set(.6,.6,1);root.add(flame);}
 root.scale.setScalar(this.fx);root.position.copy(start);root.quaternion.setFromUnitVectors(V(0,0,1),direction.clone().normalize());this.scene.add(root);const tail=this.fx>1&&kind!=='arrow'&&!arrow&&!hammer,e={root,kind,direction:direction.clone(),age:0,dead:false,trail:0,ghostAt:0,update:(pos,dt)=>{if(e.dead)return;e.age+=dt;root.position.copy(pos);e.trail+=dt;while(e.trail>.022){e.trail-=.022;this.dust(kind,pos,kind==='arrow'?1:3,kind==='arrow'?.1:.45,.25);}if(tail&&e.age>=e.ghostAt){e.ghostAt=e.age+(orb?.07:.045);this.ghost(kind,pos,(orb?1.5:.75)*this.fx,orb?.42:.26);}if(orb)root.rotation.z+=dt*4;},dispose:()=>{if(e.dead)return;e.dead=true;root.removeFromParent();root.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});}};if(!silent){this.event('release',kind,start);this.tone(kind);}return e;}
 nockedArrow(){const a=this.missile('arrow',V(),V(0,0,1),{silent:true});a.root.visible=false;return a;}
 beam(kind,start,end){const group=new T.Group(),delta=end.clone().sub(start),distance=delta.length(),direction=delta.clone().normalize(),side=V().crossVectors(direction,UP).normalize();function points(scale){const a=[];for(let i=0;i<=18;i++){const t=i/18,p=start.clone().addScaledVector(delta,t);if(i>0&&i<18)p.addScaledVector(side,(Math.random()-.5)*scale).add(V(0,(Math.random()-.5)*scale,0));a.push(p);}return a;}
 const wide=this.fx>1?1.9:1;for(const [width,color,opacity]of [[.045*wide,PALETTES[kind][0],.85],[.016*wide,PALETTES[kind][1],1]]){const mesh=new T.Mesh(new T.TubeGeometry(polyline(points(.36)),36,width,4,false),basic(color,opacity));group.add(mesh);}for(let i=0;i<(this.fx>1?6:3);i++){const t=.2+Math.random()*.6,a=start.clone().addScaledVector(delta,t),b=a.clone().addScaledVector(side,(i%2?1:-1)*(.35+Math.random()*.55)).addScaledVector(direction,.45);group.add(new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3([a,a.clone().lerp(b,.5).add(V(0,.12,0)),b]),10,.01*wide,3),basic(PALETTES[kind][0],.65)));}
 this.add(group,this.fx>1?.38:.28,(e,t)=>group.traverse(o=>{if(o.material)o.material.opacity=(t<.7?1:(1-t)/.3)*(.85+.15*Math.sin(t*70));}));this.dust(kind,end,18,2,.45);this.light(kind,end,.16,5);if(this.fx>1){this.ghost(kind,end,1.3*this.fx,.3);this.ghost(kind,start,.8*this.fx,.22);}this.event('release',kind,start);this.tone(kind);return distance;}
 ring(kind,pos,radius,life=.5){const mesh=new T.Mesh(new T.RingGeometry(this.fx>1?.8:.88,1,64),basic(PALETTES[kind][0],.6));mesh.rotation.x=-Math.PI/2;mesh.position.copy(pos);mesh.position.y=.025;this.add(mesh,life,(e,t)=>{mesh.scale.setScalar(Math.max(.02,radius*(.15+.85*t)));mesh.material.opacity=(1-t)*(this.fx>1?.85:.65);});}
 impact(kind,pos,radius=.65){this.event('impact',kind,pos);this.dust(kind,pos,kind==='fire'?44:26,kind==='ice'?3.8:3.0,.65);this.light(kind,pos,.22,kind==='fire'?9:5);const s=this.sprite(kind,1);s.position.copy(pos);this.add(s,.28,(e,t)=>{s.scale.setScalar((.5+t*3)*Math.min(1.8,radius)*this.fx);s.material.opacity=1-t;});this.ring(kind,pos,Math.max(.35,radius),.5);if(this.fx>1){const core=this.sprite(kind,1);core.material.color.setHex(PALETTES[kind][1]);core.position.copy(pos);this.add(core,.12,(e,t)=>{core.scale.setScalar((.9+t)*Math.min(1.8,radius)*this.fx);core.material.opacity=1-t;});if(radius>=.6)this.scorch(kind,pos,radius);}
 if(kind==='ice'){for(let i=0;i<10;i++){const a=i/10*Math.PI*2,r=radius*(.4+.5*Math.random()),mesh=new T.Mesh(new T.ConeGeometry(.07,.25+Math.random()*.3,5),basic(0xb4edff,.8));mesh.position.copy(pos).add(V(Math.cos(a)*r,-pos.y+.08,Math.sin(a)*r));mesh.rotation.z=(Math.random()-.5)*.6;this.add(mesh,.8,(e,t)=>{mesh.scale.y=Math.sin(Math.PI*t);mesh.material.opacity=(1-t)*.8;});}}
 }
 slash(kind,pos,radius=1){const big=this.fx>1,arc=new T.Mesh(new T.TorusGeometry(radius,big?.045:.018,4,40,Math.PI*1.25),basic(PALETTES[kind][1],.7));arc.position.copy(pos);arc.rotation.set(Math.PI/2,.3,Math.random()*2);this.add(arc,big?.26:.22,(e,t)=>{arc.rotation.z+=t*.18;arc.material.opacity=(1-t)*(big?.9:.65);});}
 vortex(pos,radius,duration=1.2){const group=new T.Group();group.position.copy(pos);const ribbons=[];for(let j=0;j<5;j++){const vertices=[],idx=[],colors=[],steps=64;for(let i=0;i<=steps;i++){const t=i/steps,a=t*Math.PI*1.45+j*Math.PI*.4,r=radius*(.80-.28*t+j*.025)*(1+.04*Math.sin(t*9+j)),y=.08+t*(.80+j*.12),w=.004+Math.sin(Math.PI*t)*.045;vertices.push(Math.sin(a)*r,y-w,Math.cos(a)*r,Math.sin(a)*r,y+w,Math.cos(a)*r);const fade=Math.sin(Math.PI*t)**1.5;colors.push(fade,fade,fade,fade,fade,fade);if(i<steps){const k=i*2;idx.push(k,k+1,k+2,k+1,k+3,k+2);}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(vertices,3));g.setIndex(idx);g.setAttribute('color',new T.Float32BufferAttribute(colors,3));const m=basic(j%2?0xd7e1db:0x9fbab7,.4);m.vertexColors=true;const mesh=new T.Mesh(g,m);group.add(mesh);ribbons.push(mesh);}
 for(let i=0;i<18;i++){const a=i/18*Math.PI*2,mesh=new T.Mesh(new T.IcosahedronGeometry(.02+Math.random()*.025),new T.MeshBasicMaterial({color:0x8b8269}));mesh.position.set(Math.sin(a)*radius*.75,.1+Math.random()*.55,Math.cos(a)*radius*.75);group.add(mesh);}this.event('vortex','wind',pos);this.tone('wind');this.add(group,duration,(e,t)=>{group.rotation.y=-t*Math.PI*7;ribbons.forEach((o,i)=>{o.material.opacity=Math.sin(Math.PI*t)*(.35+i*.025)*(this.fx>1?1.6:1);o.rotation.y=i*.7-t;});if(Math.random()<.7){const a=Math.random()*Math.PI*2,p=pos.clone().add(V(Math.sin(a)*radius,.04,Math.cos(a)*radius));this.dust('wind',p,2,.6,.25);}});return group;}
 area(kind,pos,radius=2,duration=1,{meteor=false}={}){this.event('area',kind,pos);this.ring(kind,pos,radius,duration);if(meteor){const mesh=new T.Mesh(new T.IcosahedronGeometry(.33,1),new T.MeshStandardMaterial({color:0x7b2710,emissive:0xe5510a,emissiveIntensity:2,roughness:.8}));mesh.scale.setScalar(this.fx);mesh.position.copy(pos).add(V(0,6,-1.5));const mark=new T.Mesh(new T.CircleGeometry(radius,40),basic(0xff3b1e,.12));mark.rotation.x=-Math.PI/2;mark.position.set(pos.x,.035,pos.z);this.add(mark,duration,(e,t)=>{mark.material.opacity=.10+.28*t*(.75+.25*Math.sin(t*40));});this.add(mesh,duration,(e,t)=>{mesh.position.copy(pos).add(V(0,6*(1-t),-1.5*(1-t)));mesh.rotation.x+=.08;this.dust('fire',mesh.position,3,1,.4);if(this.fx>1&&Math.random()<.5)this.ghost('fire',mesh.position,1.1*this.fx,.3);if(t>.96&&!e.impacted){e.impacted=true;this.impact(kind,pos,radius);this.ring(kind,pos,radius*1.7,.6);this.onShake?.(.5);this.area('fire',pos,radius,2.5);}});return;}
 const group=new T.Group();group.position.copy(pos);for(let i=0;i<14;i++){const a=i/14*Math.PI*2,r=radius*(.2+.7*Math.random()),s=this.sprite(kind,.5);s.position.set(Math.sin(a)*r,.15+Math.random()*.2,Math.cos(a)*r);group.add(s);}this.add(group,duration,(e,t)=>{group.children.forEach((s,i)=>{s.scale.set(.3,.5+Math.sin(t*35+i)*.25,.3);s.material.opacity=Math.sin(Math.PI*t)*.8;});if(Math.random()<.8){const a=Math.random()*Math.PI*2;this.dust(kind,pos.clone().add(V(Math.sin(a)*radius*Math.random(),.08,Math.cos(a)*radius*Math.random())),3,1.1,.45);}});}
 fireWall(a,b,duration=3.2){const group=new T.Group(),count=18;for(let i=0;i<count;i++){const t=i/(count-1),s=this.sprite('fire',.7);s.position.copy(a).lerp(b,t);s.position.y=.30;group.add(s);}this.add(group,duration,(e,t)=>{group.children.forEach((s,i)=>{s.scale.set(.45,.65+Math.sin(e.age*13+i*1.7)*.22,1);s.material.opacity=Math.min(1,e.age*5)*(1-t*.4);});if(Math.random()<.8){const p=a.clone().lerp(b,Math.random());this.dust('fire',p,3,1.5,.6);}});this.event('wall','fire',a);}
 frostNova(position,radius){this.ring('ice',position,radius,.55);this.ring('ice',position,radius,.75);for(let i=0;i<30;i++){const a=i/30*Math.PI*2,shard=new T.Mesh(new T.OctahedronGeometry(.07),basic(0xc7f4ff));shard.scale.set(.5,1,2.3);this.add(shard,.65,(e,t)=>{shard.position.copy(position).add(V(Math.sin(a)*radius*t,.10,Math.cos(a)*radius*t));shard.rotation.y=a;shard.material.opacity=1-t;});}this.event('nova','ice',position);}
 shout(position,radius,kind='physical'){for(let i=0;i<3;i++){const ring=new T.Mesh(new T.TorusGeometry(1,.017,4,56),basic(PALETTES[kind][0],.65));ring.rotation.x=Math.PI/2;ring.position.copy(position).add(V(0,.1+i*.23,0));this.add(ring,.65,(e,t)=>{ring.scale.setScalar(.2+radius*t);ring.material.opacity=(1-t)*.65;});}this.dust(kind,position.clone().setY(.7),22,3,.5);this.event('shout',kind,position);}
 ward(kind,radius=1.1,id=''){const group=new T.Group(),ring=new T.Mesh(new T.TorusGeometry(radius,.018,5,64),basic(PALETTES[kind][0],.5));ring.rotation.x=Math.PI/2;group.add(ring);for(let i=0;i<8;i++){const a=i/8*Math.PI*2,rune=new T.Mesh(new T.BoxGeometry(.035,.012,.16),basic(PALETTES[kind][1],.7));rune.position.set(Math.sin(a)*radius,.02,Math.cos(a)*radius);rune.rotation.y=a;group.add(rune);}if(id==='paladin-0-3'||id==='paladin-2-3'){const vertical=new T.Mesh(new T.TorusGeometry(.65,.018,5,48),basic(0xffd782,.5));vertical.position.set(0,.95,.35);group.add(vertical);for(const [w,h]of [[.04,.7],[.4,.04]]){const cross=new T.Mesh(new T.BoxGeometry(w,h,.02),basic(0xffedb2,.7));cross.position.set(0,1,.38);group.add(cross);}}this.scene.add(group);return group;}
 tick(dt){this.time+=dt;for(const e of this.lightPool){e.life=Math.max(0,e.life-dt);e.light.intensity=e.power*e.life/e.duration;}for(const e of this.entities){e.age+=dt;if(e.age>=e.life)this.remove(e);else e.update(e,e.age/e.life,dt);}this.entities=this.entities.filter(e=>!e.dead);for(const p of this.particles){p.age+=dt;p.v.y+=p.gravity*dt;p.p.addScaledVector(p.v,dt);}this.particles=this.particles.filter(p=>p.age<p.life);for(let i=0;i<this.particles.length;i++){const p=this.particles[i],fade=1-p.age/p.life;this.positions.set(p.p.toArray(),i*3);this.colors.set([p.color.r*fade,p.color.g*fade,p.color.b*fade],i*3);}this.points.geometry.setDrawRange(0,this.particles.length);this.points.geometry.attributes.position.needsUpdate=true;this.points.geometry.attributes.color.needsUpdate=true;}
 clear(){for(const e of this.lightPool){e.life=0;e.light.intensity=0;}for(const e of this.entities)this.remove(e);this.entities=[];this.particles=[];this.points.geometry.setDrawRange(0,0);}
 toggleSound(){return audio.toggle();}
 tone(kind){}
 snapshot(){return{entities:this.entities.length,particles:this.particles.length,maxParticles:this.maxParticles,sound:this.sound,history:this.history.slice(-40)};}
}

function polyline(points){const curve=new T.Curve();curve.getPoint=(t,target=new T.Vector3())=>{const f=t*(points.length-1),i=Math.min(points.length-2,Math.floor(f));return target.copy(points[i]).lerp(points[i+1],f-i);};return curve;}
